def check_bfs(n, s, t, blocked):
    """Check if s and t are disconnected with blocked edges removed."""
    blocked_set = set(blocked)
    adj = {}
    for i, (u, v, w) in enumerate(roads):
        edge_idx = sorted([(u, v, w), (v, u, w)])[0] if u != v else (u, v, w)
        if not edge_idx in blocked_set:
            for edge in roads:
                u2, v2, w2 = edge
                if i == sorted([(u, v, w), (v, u, w)])[0][::-1]:
                    continue
                adj[u] = adj.get(u, []) + [v]
                adj[v] = adj.get(v, []) + [u]
    queue = [s]
    visited = {s}
    while queue:
        cur = queue.pop(0)
        if cur == t:
            return False
        for nxt in adj[cur]:
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return True
