def solution(input_str):
    n, p, l, r = map(int, input_str.strip().split())

    # We need to count valid permutations where we have a customers of type A (50 yuan),
    # b customers of type B (100 yuan, need change), c customers of type C (VIP).
    # a + b + c = n
    # At no point can balance (50 notes held) go below 0
    # Final notes = a, must be in [l, r]
    #
    # For fixed a, b: valid permutations = C(n, a+b) * C(a+b, a) - invalid
    # This equals: C(n, a+b) * C(a+b, a) using Catalan-like counting
    # 
    # Actually, with 3 types, after fixing a, b, c counts:
    # Valid arrangements = C(a+b+c, a+b) * valid(a, b)
    # Valid(a, b) = (a - b + 1) / (a + 1) * C(a + b, a) for a >= b
    # Otherwise 0

    result = 0
    for a in range(l, min(r, n) + 1):
        for b in range(0, min(n - a, n - l + 1)):
            c = n - a - b
            if a < b:
                continue
            # Valid arrangements
            # Choose positions for A and B combined: C(n, a+b)
            # Given a positions for A and B, valid = (a - b + 1)/(a + 1) * C(a + b, a)
            # Then multiply by 1 for C remaining positions (they are all same)

            mod = p
            # C(a+b, a) = C(n, a+b) * C(a+b, a) is wrong, let me recalc
            # First place a+b customers (A and B), then c positions for C

            # Number of valid A-B sequences with a A's and b B's where prefixes have a_i >= b_i
            # This is the ballot problem: (a - b + 1) / (a + 1) * C(a + b, a)

            numerator = (a - b + 1) * nCr(a + b, a, mod)
            denominator = a + 1
            valid_ab = (numerator * pow(denominator, mod - 2, mod)) % mod

            result = (result + nCr(n, a + b) * valid_ab) % mod

    return str(result)
