import sys
sys.setrecursionlimit(200000)

def solution(input_str):
    n, p, l_val, r_val = map(int, input_str.strip().split())
    l, r = l_val, r_val

    def nCr_mod(n, r_mod, p):
        if r_mod < 0 or r_mod > n:
            return 0
        if r_mod == 0 or r_mod == n:
            return 1
        if r_mod > n - r_mod:
            r_mod = n - r_mod

        num = 1
        den = 1
        for i in range(r_mod):
            num = num * (n - i) % p
            den = den * (i + 1) % p
        return num * pow(den, p - 2, p) % p

    def iter_partitions(target):
        for c_val in range(target + 1):
            remaining = target - c_val
            a = 0
            while a <= remaining:
                b = remaining - a
                yield a, b, c_val
                a += 1

    result = 0
    for a in range(l, r + 1):
        if a > n:
            break
        rem = n - a
        for b in range(0, rem + 1):
            c = rem - b
            if b > a:
                continue

            # Valid A-B permutations: (a - b + 1) / (a + 1) * C(a + b, a)
            val_ab = nCr_mod(a + b, b, p)
            bal = a - b + 1
            total_ab = val_ab * bal % p
            total_ab = total_ab * pow(a + 1, p - 2, p) % p

            result = result * nCr_mod(n, a + b, p) * total_ab % p
            result = result % p

    return str(result)
